function goldReward(position,amount=1){if(amount<=0)return;sound('coin',.8);if(reduced.matches){toast('+'+amount+' coins');return;}const coin=document.createElement('span'),p=world.project(position,1.2),target=$('gold').getBoundingClientRect(),gameRect=$('game').getBoundingClientRect();coin.className='gold-flight';coin.textContent='◉ +'+amount;$('game').append(coin);const animation=coin.animate([{left:p.x+'px',top:p.y+'px',transform:'translate(-50%,-50%) scale(.7)',opacity:0},{left:(p.x+18)+'px',top:(p.y-35)+'px',transform:'translate(-50%,-50%) scale(1.2)',opacity:1,offset:.2},{left:(target.x-gameRect.left+target.width/2)+'px',top:(target.y-gameRect.top+12)+'px',transform:'translate(-50%,-50%) scale(.65)',opacity:0}],{duration:650,easing:'cubic-bezier(.2,.7,.3,1)',fill:'forwards'});animation.onfinish=animation.oncancel=()=>coin.remove();}
