function nextNode(){const a=s.town.active,o=currentOffer();if(a?.status==='won'||a?.type==='convoy')return 'lodge';if(a?.type==='timber')return 'wood';if(a?.type==='supply'){const spec=jobSpec(a.type,a.variant),r=shipmentRecipe(s,spec.recipe),loads=Math.max(1,spec.loads-a.loads-(s.orders.reserved&&s.orders.activeKind===spec.recipe?1:0));return s.food<o.food+r.food*loads?'food':'wood';}if(s.commerce.level===7&&!o.action)return 'market';if(COMMERCE_RECIPES[o.action])return o.gated||s.gold<1&&o.gold?commerceTask(s):o.node;if(o.gate)return o.gate.node;if(s.wood<o.wood&&townUnlocked(s)&&!TREES.some(t=>treeAlive(s,t)))return 'lodge';if(s.stone<(o.stone||0))return s.expansion.outpost===1&&s.expansion.stock>0?'collect':'stone';if(o.node==='lodge'&&o.gated)return 'lodge';if(!o.action)return s.expansion.outpost===4?(s.expansion.trees.cleared.length<12?'wood':s.expansion.rocks.cleared.length<10?'stone':'ship'):townUnlocked(s)?'lodge':'workshop';if(clearedCount(s)<o.trees)return 'wood';if(o.action==='triple'&&!s.orders.woodCompleted)return 'ship';return s.wood<o.wood?'wood':s.food<o.food?'food':s.gold<o.gold?(s.stage===3?'ship':'wood'):o.node;}
